  put(rt::KvKey{"ubq_ai", "api_keys", "usage", keyId}, json::object{{"key_id", keyId}}); put(rt::KvKey{"ubq_ai", "api_keys", "usage_daily", keyId}, json::object{{"key_id", keyId}, {"days", json::array()}}); put(rt::KvKey{"uos_ai", "paid_fallback", "ledger", keyId, now, "request-delete"}, json::object{{"id", "request-delete"}, {"key_id", keyId}}); put(rt::KvKey{"ubq_ai", "api_keys", "request_log", keyId, now, "legacy-request-delete"}, json::object{{"id", "legacy-request-delete"}, {"key_id", keyId}});
  kvStore.set(keyToString(rt::KvKey{"uos_ai", "api_key_usage", "v2", keyId, "policy", now}), rt::KvValue::object({{"value", rt::KvValue(rt::BigInt(1))}}));
  put(rt::KvKey{"uos_ai", "paid_fallback", "v3", "request", keyId, "request-v3-settled"}, json::object{{"v", 3}, {"key_id", keyId}, {"request_id", "request-v3-settled"}, {"billing_state", "settled"}}); put(rt::KvKey{"uos_ai", "paid_fallback", "v3", "request", keyId, "request-v3-not-billed"}, json::object{{"v", 3}, {"key_id", keyId}, {"request_id", "request-v3-not-billed"}, {"billing_state", "not_billed"}}); put(rt::KvKey{"uos_ai", "paid_fallback", "v3", "window", keyId, now + 60000}, json::object{{"v", 3}, {"key_id", keyId}, {"window_reset_at_ms", now + 60000}, {"settled_microcredits", 28992}, {"reserved_microcredits", 0}, {"pending_count", 0}}); put(rt::KvKey{"uos_ai", "paid_fallback", "v3", "reconciliation_lease", keyId}, json::object{{"token", "stale-delete-lease"}, {"expires_at_ms", now + 60000}});
  const rt::KvKey neighborPaid{"uos_ai", "paid_fallback", "ledger", neighboringKeyId, now, "request-neighbor"}, neighborLegacy{"ubq_ai", "api_keys", "request_log", neighboringKeyId, now, "legacy-request-neighbor"}, neighborCounter{"uos_ai", "api_key_usage", "v2", neighboringKeyId, "policy", now}, neighborRequest{"uos_ai", "paid_fallback", "v3", "request", neighboringKeyId, "request-v3-neighbor"};
  put(neighborPaid, json::object{{"id", "request-neighbor"}, {"key_id", neighboringKeyId}}); put(neighborLegacy, json::object{{"id", "legacy-request-neighbor"}, {"key_id", neighboringKeyId}}); kvStore.set(keyToString(neighborCounter), rt::KvValue::object({{"value", rt::KvValue(rt::BigInt(1))}})); put(neighborRequest, json::object{{"v", 3}, {"key_id", neighboringKeyId}, {"request_id", "request-v3-neighbor"}, {"billing_state", "settled"}});
  const auto deleteRequest = [&] { return handleAdminApiKeysDelete(request(json::object{{"id", keyId}}, "DELETE")); };
  const rt::KvKey unresolvedRequest{"uos_ai", "paid_fallback", "v3", "request", keyId, "request-v3-unresolved"}, unresolvedPending{"uos_ai", "paid_fallback", "v3", "pending", keyId, "request-v3-unresolved"}, deletionGuard{"uos_ai", "paid_fallback", "v3", "deletion_guard", keyId};
  put(unresolvedRequest, json::object{{"v", 3}, {"key_id", keyId}, {"request_id", "request-v3-unresolved"}, {"billing_state", "unresolved"}}); put(unresolvedPending, json::object{{"created_at_ms", now - 86400000}, {"next_reconciliation_at_ms", now + 60000}});
  setAtomicCommitsToFail(1); AWAIT(guardConflict, deleteRequest()); EXPECT_EQ(guardConflict.status(), 409); EXPECT(!kvStoreHasPrefix(deletionGuard)); EXPECT(kvStore.has(keyToString(unresolvedRequest)));
  AWAIT(blocked, deleteRequest()); EXPECT_EQ(blocked.status(), 409); AWAIT(blockedPayload, blocked.json()); const auto& error = member(blockedPayload, "error"); EXPECT_EQ(str(error, "code"), "paid_fallback_billing_outstanding"); EXPECT(rt::Regex("unresolved=1").test(str(error, "message"))); EXPECT(rt::Regex("markers=1").test(str(error, "message"))); EXPECT(kvStore.has(keyToString(rt::KvKey{"ubq_ai", "api_keys", "id", keyId}))); EXPECT(kvStoreHasPrefix(deletionGuard)); kvStore.delete_(keyToString(unresolvedRequest)); kvStore.delete_(keyToString(unresolvedPending));
  setAtomicCommitsBeforeFailure(1); AWAIT(conflicted, deleteRequest()); EXPECT_EQ(conflicted.status(), 409); EXPECT(kvStore.has(keyToString(rt::KvKey{"ubq_ai", "api_keys", "id", keyId}))); EXPECT(kvStore.has(keyToString(rt::KvKey{"ubq_ai", "api_keys", "hash", hash}))); EXPECT(kvStoreHasPrefix(rt::KvKey{"uos_ai", "paid_fallback", "ledger", keyId})); EXPECT(!kvStoreHasPrefix(rt::KvKey{"uos_ai", "paid_fallback", "v3", "request", keyId})); EXPECT(!kvStoreHasPrefix(rt::KvKey{"uos_ai", "paid_fallback", "v3", "window", keyId})); EXPECT(kvStoreHasPrefix(deletionGuard)); EXPECT(kvStoreHasPrefix(rt::KvKey{"ubq_ai", "api_keys", "request_log", keyId})); EXPECT(kvStoreHasPrefix(rt::KvKey{"uos_ai", "api_key_usage", "v2", keyId}));
